import { useState } from 'react';
import { sources } from '../data/sources';

export default function useNormalFlightSearch() {
  const [searchResults, setSearchResults] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [pagination, setPagination] = useState({
    current: 1,
    pageSize: 25,
    total: 0,
  });
  const [errors, setErrors] = useState({});

  const handleSearch = async (searchParams) => {
    const { path, sourcesExcluded, apiKey, dateRange } = searchParams;

    // Reset errors
    setErrors({});

    // Validate mandatory fields
    if (!path) {
      setErrors({ path: 'Path is required' });
      return;
    }

    if (!apiKey) {
      setErrors({ apiKey: 'API Key is required' });
      return;
    }

    if (!dateRange) {
      setErrors({ dateRange: 'Date range is required' });
      return;
    }

    // Get all source codenames except excluded ones
    const availableSources = sources
      .filter(source => !sourcesExcluded.includes(source.codename))
      .map(source => source.codename)
      .join(',');

    setIsLoading(true);
    try {
      const response = await fetch('http://backend-284998006367.us-central1.run.app/api/availability-v2', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Partner-Authorization': apiKey
        },
        body: JSON.stringify({
          routeId: path,
          startDate: dateRange[0],
          endDate: dateRange[1],
          sources: availableSources
        })
      });

      if (!response.ok) {
        throw new Error('Search failed');
      }

      const data = await response.json();
      setSearchResults(data);
      setPagination(prev => ({
        ...prev,
        total: data.routes?.length || 0
      }));
    } catch (error) {
      console.error('Search failed:', error);
      setErrors({ general: 'Search failed. Please try again.' });
    } finally {
      setIsLoading(false);
    }
  };

  const handleTableChange = (newPagination) => {
    setPagination(newPagination);
  };

  return {
    searchResults,
    isLoading,
    handleSearch,
    pagination,
    handleTableChange,
    errors
  };
}
